/* vuln.c — уязвимая версия (до патча) */
extern long read(int, void *, unsigned long);
extern void *memcpy(void *, const void *, unsigned long);
static char dst[64];
long copy_from_user(void){
  int len;                       /* <-- ЗНАКОВЫЙ размер */
  read(0, &len, 4);
  memcpy(dst, "AAAA", len);
  return len;
}

/* fixed.c — после патча */
extern long read(int, void *, unsigned long);
extern void *memcpy(void *, const void *, unsigned long);
static char dst[64];
long copy_from_user(void){
  size_t len;                    /* <-- ИСПРАВЛЕНО: беззнаковый размер */
  read(0, &len, 4);
  if (len > sizeof(dst)) return -1;   /* <-- добавлена проверка границ */
  memcpy(dst, "AAAA", len);
  return len;
}
